// Find max sum of k consecutive numbers
function maxWindowSum(nums: number[], k: number): number {
  // Calculate first window
  let windowSum = nums.slice(0, k).reduce((total, val) => total + val, 0)
  let maxSum = windowSum

  // Slide the window
  for (let i = k; i < nums.length; i++) {
    windowSum += nums[i] - nums[i - k]  // add new, remove old
    maxSum = Math.max(maxSum, windowSum)
  }

  return maxSum
}

maxWindowSum([2, 1, 5, 1, 3, 2], 3)  // 9 (5+1+3)

// Check if array has two numbers that sum to target
function twoSum(nums: number[], target: number): boolean {
  let left = 0
  let right = nums.length - 1

  while (left < right) {
    const sum = nums[left] + nums[right]
    if (sum === target) return true
    if (sum < target) left++   // need bigger number
    if (sum > target) right--  // need smaller number
  }

  return false
}

// Count character frequency
function charCount(str: string): Record<string, number> {
  const count: Record<string, number> = {}

  for (const char of str) {
    count[char] = (count[char] || 0) + 1
  }

  return count
}

charCount("hello")
// { h: 1, e: 1, l: 2, o: 1 }

// Find first non-repeating character
function firstUnique(str: string): string {
  const count = charCount(str)

  for (const char of str) {
    if (count[char] === 1) return char
  }

  return ""
}

